export function boardToSource(point: Point2, camera: CameraPose): Point2 {
  return { x: (point.x - camera.x) / camera.scale, y: (camera.y - point.y) / camera.scale };
}

/** Left edge stays attached; uncompressed strips descend as contact travels left→right. */
export function pressStripLift(normalizedX: number, progress: number, height: number): number {
  const x = clamp(normalizedX, 0, 1);
  const contact = smooth((progress * 1.32 - x) / 0.32);
  const unpressed = 1 - contact;
  return height * 0.04 * unpressed * Math.sin(x * Math.PI / 2);
}

/** Continuous shallow cylinder, in native top-left pixels. Caller owns `out`. */
export function pressPaperPoint(pixelX: number, pixelY: number, width: number, height: number,
  progress: number, out: Point2): Point2 {
  const p = clamp(Number.isFinite(progress) ? progress : 0, 0, 1);
  const eased = smooth(p);
  const flat = width * (0.07 + 0.93 * eased);
  const remaining = width - flat;
  if (!(width > 0 && height > 0) || p >= 1 || remaining < 0.000001 || pixelX <= flat) {
    out.x = pixelX; out.y = pixelY; return out;
  }
  // Same moving flat edge / cylindrical arc as the web reference, with a much
  // low lift. A fuller arc makes the left-to-right spread readable while the
  // height cap stays fixed; the paper node never scales to squeeze.
  const initialAngle = 0.75;
  const angle = 0.72 * Math.pow(1 - eased, 0.7) + 0.03;
  const radius = remaining / angle;
  const distance = Math.min(pixelX - flat, remaining);
  const theta = distance / radius;
  const initialRise = width * 0.93 / initialAngle * (1 - Math.cos(initialAngle));
  const projection = Math.min(0.72, height / (width * 0.9), height * 0.04 / initialRise);
  out.x = flat + radius * Math.sin(theta) + Math.max(0, pixelX - width);
  out.y = pixelY - radius * (1 - Math.cos(theta)) * projection;
  return out;
}

/** Tiny continuous peel at the right22%; no horizontal compression. */
export function pickupPaperPoint(pixelX: number, pixelY: number, width: number, height: number,
  progress: number, out: Point2): Point2 {
  const p = clamp(Number.isFinite(progress) ? progress : 0, 0, 1);
  const edge = width > 0 ? smooth((pixelX / width - 0.78) / 0.22) : 0;
  const peel = p <= 0 || p >= 1 ? 0 : Math.sin(p * Math.PI);
  out.x = pixelX;
  out.y = pixelY - Math.max(0, height) * 0.02 * edge * peel;
  return out;
}

export function pressStrip(normalizedX: number, progress: number, height: number): { lift: number; angle: number; widthScale: number } {
  // Rotating or narrowing separate strips tears the illustration into a squeezed fan.
  return { lift: pressStripLift(normalizedX, progress, height), angle: 0, widthScale: 1 };
}

/** Small pickup fold restricted to the last 26% of the paper; no whole-object scaling. */
export function pickupStrip(normalizedX: number, progress: number, height: number): { lift: number; angle: number; widthScale: number } {
  const curl = smooth((normalizedX - 0.74) / 0.26) * Math.sin(clamp(progress, 0, 1) * Math.PI);
  return { lift: height * 0.075 * curl, angle: 10 * curl, widthScale: Math.max(0.96, Math.cos(curl * 0.2)) };

